  std::any parseMarketLeverageTiers(std::any info,
                                    std::any market = std::any{}) override {
    //
    //     {
    //         "symbol": "rad_usdt",
    //         "leverageBrackets": [
    //             {
    //                 "symbol": "rad_usdt",
    //                 "bracket": 1,
    //                 "maxNominalValue": "5000",
    //                 "maintMarginRate": "0.025",
    //                 "startMarginRate": "0.05",
    //                 "maxStartMarginRate": null,
    //                 "maxLeverage": "20",
    //                 "minLeverage": "1"
    //             },
    //         ]
    //     }
    //
    std::any tiers = ccxt::list{};
    std::any brackets =
        this->safeList(info, std::string("leverageBrackets"), ccxt::list{});
    for (std::any i = 0; isLessThan(i, getArrayLength(brackets));
         postFixIncrement(i)) {
      std::any tier = ::getValue(brackets, i);
      std::any marketId = this->safeString(info, std::string("symbol"));
      market = this->safeMarket(marketId, market, std::string("_"),
                                std::string("contract"));
      std::any minNotional =
          this->safeNumber(::getValue(brackets, subtract(i, 1)),
                           std::string("maxNominalValue"), 0);
      arrayPush(tiers,
                ccxt::dict{
                    {std::string("tier"),
                     this->safeInteger(tier, std::string("bracket"))},
                    {std::string("symbol"),
                     this->safeSymbol(marketId, market, std::string("_"),
                                      std::string("contract"))},
                    {std::string("currency"),
                     ::getValue(market, std::string("settle"))},
                    {std::string("minNotional"), minNotional},
                    {std::string("maxNotional"),
                     this->safeNumber(tier, std::string("maxNominalValue"))},
                    {std::string("maintenanceMarginRate"),
                     this->safeNumber(tier, std::string("maintMarginRate"))},
                    {std::string("maxLeverage"),
                     this->safeNumber(tier, std::string("maxLeverage"))},
                    {std::string("info"), tier},
                });
    }
    return tiers;
  }

  /**
   * @method
   * @name xt#fetchFundingRateHistory
   * @description fetches historical funding rates
   * @see https://doc.xt.com/docs/futures/MarketData/get-funding-rate-records
   * @param {string} [symbol] unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures] to
   * fetch
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @param {bool} params.paginate true/false whether to use the pagination
   * helper to aumatically paginate through the results
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/en/latest/manual.html?#funding-rate-history-structure}
   */
  std::shared_future<std::any> fetchFundingRateHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(symbol, std::any{}))) {
                  throw ArgumentsRequired(toString(add(
                      this->id, std::string(" fetchFundingRateHistory() "
                                            "requires a symbol argument"))));
                }
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any paginate = false;
                std::any paginateparamsVariable = this->handleOptionAndParams(
                    params, std::string("fetchFundingRateHistory"),
                    std::string("paginate"));
                paginate = ::getValue(paginateparamsVariable, 0);
                params = ::getValue(paginateparamsVariable, 1);
                if (isTrue(paginate)) {
                  return awaitValue(this->fetchPaginatedCallCursor(
                      std::string("fetchFundingRateHistory"), symbol, since,
                      limit, params, std::string("id"), std::string("id"), 1,
                      200));
                }
                std::any market = this->market(symbol);
                if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                  throw NotSupported(toString(add(
                      this->id, std::string(" fetchFundingRateHistory() "
                                            "supports swap contracts only"))));
                }
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                if (isTrue(!isEqual(limit, std::any{}))) {
                  ::setValue(request, std::string("limit"), limit);
                } else {
                  ::setValue(request, std::string("limit"), 200); // max
                }
                std::any subType = std::any{};
                std::any subTypeparamsVariable = this->handleSubTypeAndParams(
                    std::string("fetchFundingRateHistory"), market, params);
                subType = ::getValue(subTypeparamsVariable, 0);
                params = ::getValue(subTypeparamsVariable, 1);
                std::any response = std::any{};
                if (isTrue(isEqual(subType, std::string("inverse")))) {
                  response = awaitValue(
                      this->publicInverseGetFutureMarketV1PublicQFundingRateRecord(
                          this->extend(request, params)));
                } else {
                  response = awaitValue(
                      this->publicLinearGetFutureMarketV1PublicQFundingRateRecord(
                          this->extend(request, params)));
                }
                //
                //     {
                //         "returnCode": 0,
                //         "msgInfo": "success",
                //         "error": null,
                //         "result": {
                //             "hasPrev": false,
                //             "hasNext": true,
                //             "items": [
                //                 {
                //                     "id": "210441653482221888",
                //                     "symbol": "btc_usdt",
                //                     "fundingRate": "0.000057",
                //                     "createdTime": 1679875200000,
                //                     "collectionInternal": 28800
                //                 },
                //             ]
                //         }
                //     }
                //
                std::any result = this->safeDict(
                    response, std::string("result"), ccxt::dict{});
                std::any items =
                    this->safeList(result, std::string("items"), ccxt::list{});
                std::any rates = ccxt::list{};
                for (std::any i = 0; isLessThan(i, getArrayLength(items));
                     postFixIncrement(i)) {
                  std::any entry = ::getValue(items, i);
                  std::any marketId =
                      this->safeString(entry, std::string("symbol"));
                  std::any symbolInner = this->safeSymbol(marketId, market);
                  std::any timestamp =
                      this->safeInteger(entry, std::string("createdTime"));
                  arrayPush(
                      rates,
                      ccxt::dict{
                          {std::string("info"), entry},
                          {std::string("symbol"), symbolInner},
                          {std::string("fundingRate"),
                           this->safeNumber(entry, std::string("fundingRate"))},
                          {std::string("timestamp"), timestamp},
                          {std::string("datetime"), this->iso8601(timestamp)},
                      });
                }
                std::any sorted = this->sortBy(rates, std::string("timestamp"));
                return this->filterBySymbolSinceLimit(
                    sorted, ::getValue(market, std::string("symbol")), since,
                    limit);
              })
            .share();
  }

